/**
 * Upload dialogue for the Large file repository.
 *
 * Subscribes to the file picker's upload event, opens a dialogue offering a
 * chunked upload from the user's computer or a server-side fetch from a URL, and
 * refreshes the picker listing once a file has been staged. The chunk loop
 * retries transient failures with exponential backoff and reconciles its resume
 * position with the server, so a large upload survives a dropped chunk. If the
 * page is left mid-upload, the server keeps the partial file and this module
 * remembers it (in localStorage), so re-selecting the same file on return carries
 * on from where it stopped instead of starting over. Where the browser supports it
 * (Chrome/Edge, secure context), an optional Background Fetch mode uploads the file
 * through a service worker so it continues even after the tab is closed; those
 * chunks arrive out of order and the server reassembles them.
 *
 * @module     repository_largefile/upload
 * @copyright  2026 Vernon Spain
 * @copyright  2020 Justus Dieckmann WWU
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import {subscribe} from 'core/pubsub';
import SaveCancelModal from 'core/modal_save_cancel';
import ModalEvents from 'core/modal_events';
import Templates from 'core/templates';
import {getString} from 'core/str';
import Notification from 'core/notification';
import * as config from 'core/config';

/** @constant {string} Upload endpoint, relative to wwwroot. */
const ENDPOINT = '/repository/largefile/upload_ajax.php';

/** @constant {number} How many times to retry a chunk after a transient failure. */
const MAX_RETRIES = 5;

/** @constant {number} Base backoff between retries in ms; doubles each attempt up to the cap. */
const BACKOFF_BASE_MS = 1000;

/** @constant {number} Upper bound on a single backoff wait in ms. */
const BACKOFF_CAP_MS = 16000;

/** @constant {number} Server-side "upload completed" state (mirrors chunk_store). */
const STATE_COMPLETED = 2;

/** @constant {string} localStorage key holding per-context resume records. */
const RESUME_KEY = 'repository_largefile_resume';

/**
 * @constant {number} Prune a resume record from localStorage once it is this old.
 * This has no say in whether a resume is offered — the server is the sole authority
 * there, a resume being offered only after {@see validateResume} confirms the token
 * still exists — so it is purely storage hygiene, set well beyond any realistic
 * server retention so it never forgets a partial the server would still resume.
 */
const RESUME_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/** @constant {string} localStorage key holding background-upload recovery records, keyed by token. */
const RESUME_BG_KEY = 'repository_largefile_resume_bg';

/**
 * @constant {number} Prune a background recovery record after this long. Unlike the
 * foreground slot this is generous (a day): a Background Fetch upload can run for
 * hours, and whether it is still recoverable is decided by asking the server, not
 * by this bound — so it must not age a still-uploading record out prematurely.
 */
const RESUME_BG_TTL_MS = 24 * 60 * 60 * 1000;

/**
 * @constant {boolean} Whether this browser can continue an upload after the tab is
 * closed: a secure context with a service worker and the Background Fetch API
 * (Chrome/Edge). Elsewhere the upload is foreground-only (with resume).
 */
const BG_SUPPORTED = typeof window !== 'undefined' && window.isSecureContext
    && 'serviceWorker' in navigator && 'BackgroundFetchManager' in window;

/** @var {boolean} Whether the pubsub listener has been registered. */
let listenersRegistered = false;

/** @var {Promise|null} Memoised service-worker registration for Background Fetch. */
let swRegistrationPromise = null;

/** @var {boolean} Whether the module-level service-worker message listener is set. */
let swMessageListenerRegistered = false;

/**
 * @var {Map<string,Function>} Completion callbacks keyed by the Background
 * Fetch registration id, so the service worker's `bgcomplete` message wakes
 * only the callback that belongs to the upload that finished — not every
 * callback registered by every upload on the page. Without this, two
 * concurrent background uploads on the same page would fire each other's
 * success notification on the first one to complete.
 */
const bgCompletionCallbacks = new Map();

/**
 * Register (once, at module scope so it outlives any dialogue) a listener for the
 * service worker's background-fetch completion message, waking only the
 * callback registered for the completed upload's Background Fetch registration
 * id. The per-dialogue listener would be gone by the time the upload finishes,
 * so completion is handled here instead.
 *
 * @return {void}
 */
const ensureSwMessageListener = () => {
    if (swMessageListenerRegistered || !BG_SUPPORTED || !navigator.serviceWorker) {
        return;
    }
    swMessageListenerRegistered = true;
    navigator.serviceWorker.addEventListener('message', (e) => {
        if (!e.data || e.data.type !== 'repository_largefile_bgcomplete' || !e.data.id) {
            return;
        }
        const callback = bgCompletionCallbacks.get(e.data.id);
        if (callback) {
            bgCompletionCallbacks.delete(e.data.id);
            callback();
        }
    });
};

/**
 * Register (once) the plugin's service worker, which owns Background Fetch uploads
 * so they continue after the page closes. Its scope is the plugin directory, which
 * covers the upload endpoint.
 *
 * @return {Promise} Resolves with the ServiceWorkerRegistration.
 */
const getServiceWorker = () => {
    if (swRegistrationPromise === null) {
        swRegistrationPromise = registerServiceWorker(config.wwwroot + '/repository/largefile/');
    }
    return swRegistrationPromise;
};

/**
 * Register the service worker at the given scope and wait until it is active.
 *
 * @param {string} scope The scope URL (the plugin directory).
 * @return {Promise} Resolves with the active ServiceWorkerRegistration.
 */
const registerServiceWorker = async(scope) => {
    const registration = await navigator.serviceWorker.register(scope + 'sw.js', {scope});
    await waitForActive(registration);
    return registration;
};

/**
 * Resolve once a service-worker registration has an active worker. This does not
 * use navigator.serviceWorker.ready, which waits for the worker that controls the
 * *current page* — our worker is scoped to the plugin directory and does not
 * control the file-picker page it is registered from, so `ready` would never
 * resolve there.
 *
 * @param {ServiceWorkerRegistration} registration The registration to await.
 * @return {Promise} Resolves when the registration is active.
 */
const waitForActive = (registration) => {
    if (registration.active) {
        return Promise.resolve();
    }
    const worker = registration.installing || registration.waiting;
    if (!worker) {
        return Promise.resolve();
    }
    return new Promise((resolve) => {
        worker.addEventListener('statechange', () => {
            if (worker.state === 'activated') {
                resolve();
            }
        });
    });
};

/**
 * Hand a local file to the browser's Background Fetch so its chunks keep uploading
 * even after this page is closed. Each chunk is an independent POST to bgchunk that
 * the server writes at its byte offset; the server marks the upload complete once
 * every byte has arrived, so the chunks may run in any order.
 *
 * @param {File} file The file to upload.
 * @param {object} token The {id, chunksize, maxbytes} allocated for it.
 * @return {Promise} Resolves once the background fetch is registered.
 */
const startBackgroundUpload = async(file, token) => {
    // Record the total length and file name up front — chunks arrive out of order,
    // possibly after the page has gone, so the accepted-type policy is enforced now.
    const started = await postRequest(
        {action: 'bgstart', id: token.id, length: file.size, filename: file.name}, null, null, null, null);
    const startedResponse = parseJson(started.text);
    if (started.status !== 200 || startedResponse === null || startedResponse.error !== undefined) {
        throw new Error(startedResponse && startedResponse.error
            ? startedResponse.error : await getString('erroruploadfailed', 'repository_largefile'));
    }
    const registration = await getServiceWorker();
    const chunkSize = token.chunksize;
    const requests = [];
    for (let start = 0; start < file.size; start += chunkSize) {
        const end = Math.min(start + chunkSize, file.size);
        const qs = 'action=bgchunk&id=' + encodeURIComponent(token.id)
            + '&start=' + start + '&end=' + end + '&sesskey=' + encodeURIComponent(config.sesskey);
        requests.push(new Request(config.wwwroot + ENDPOINT + '?' + qs, {
            method: 'post',
            body: file.slice(start, end),
            headers: {'Content-Type': 'application/octet-stream'},
        }));
    }
    // These requests upload the file slices (Background Fetch derives uploadTotal
    // from their bodies); the responses are only small JSON, so downloadTotal is
    // left at its default — declaring the file size there would make the browser
    // expect a whole file back and can fail the fetch with download-total-exceeded.
    await registration.backgroundFetch.fetch('repository_largefile-' + token.id, requests, {
        title: file.name,
    });
};

/**
 * Read the whole resume map from localStorage, tolerating storage being
 * unavailable or corrupt (private-browsing, cleared site data, quota).
 *
 * @return {object} Map of contextId to a resume record.
 */
const readResumeMap = () => {
    try {
        return JSON.parse(window.localStorage.getItem(RESUME_KEY) || '{}') || {};
    } catch (e) {
        return {};
    }
};

/**
 * Store (or, when rec is null, clear) the resume record for a context, pruning
 * expired entries. Any storage failure is ignored — resume is a convenience.
 *
 * @param {number} contextId The context id the upload belongs to.
 * @param {object|null} rec The record to store, or null to remove it.
 * @return {void}
 */
const writeResume = (contextId, rec) => {
    try {
        const map = readResumeMap();
        const now = Date.now();
        Object.keys(map).forEach((key) => {
            if (!map[key] || (now - (map[key].updated || 0)) > RESUME_TTL_MS) {
                delete map[key];
            }
        });
        if (rec) {
            map[contextId] = Object.assign({}, rec, {updated: now});
        } else {
            delete map[contextId];
        }
        window.localStorage.setItem(RESUME_KEY, JSON.stringify(map));
    } catch (e) {
        // Storage unavailable; resume-across-navigation simply is not offered.
    }
};

/**
 * The stored resume record for a context, or null when there is none. Age is not
 * judged here: the server decides whether the partial still exists (the record is
 * validated against it before any resume is offered), so a record is kept until the
 * server rejects its token — a pause longer than a fixed client bound no longer
 * loses a partial the server has retained.
 *
 * @param {number} contextId The context id.
 * @return {object|null} The record, or null.
 */
const readResume = (contextId) => {
    return readResumeMap()[contextId] || null;
};

/**
 * Read the background-upload recovery map (token -> record). Separate from the
 * per-context foreground slot: a Background Fetch upload is owned by the browser
 * and the server, not the dialogue, so its recovery record must survive a dialogue
 * being opened and closed, several may run at once, and closing a dialogue must
 * never delete one. Tolerates storage being unavailable or corrupt.
 *
 * @return {object} Map of token to a background recovery record.
 */
const readBgMap = () => {
    try {
        return JSON.parse(window.localStorage.getItem(RESUME_BG_KEY) || '{}') || {};
    } catch (e) {
        return {};
    }
};

/**
 * Store (rec) or remove (rec null) a background recovery record for a token,
 * pruning entries past their bound. Keyed by token so concurrent background
 * uploads in the same context never overwrite each other. Storage failures are
 * ignored — recovery is a convenience.
 *
 * @param {string} token The upload token id.
 * @param {object|null} rec The record to store, or null to remove it.
 * @return {void}
 */
const writeBgRecord = (token, rec) => {
    try {
        const map = readBgMap();
        const now = Date.now();
        Object.keys(map).forEach((key) => {
            if (!map[key] || (now - (map[key].updated || 0)) > RESUME_BG_TTL_MS) {
                delete map[key];
            }
        });
        if (rec) {
            map[token] = Object.assign({}, rec, {updated: now});
        } else {
            delete map[token];
        }
        window.localStorage.setItem(RESUME_BG_KEY, JSON.stringify(map));
    } catch (e) {
        // Storage unavailable; background recovery simply is not offered.
    }
};

/**
 * The background recovery records belonging to a context (each with its token),
 * newest first, dropping any past their bound.
 *
 * @param {number} contextId The context id.
 * @return {Array} List of records, each including its `token`.
 */
const bgRecordsForContext = (contextId) => {
    const map = readBgMap();
    const now = Date.now();
    return Object.keys(map)
        .filter((token) => map[token] && map[token].contextId === contextId
            && (now - (map[token].updated || 0)) <= RESUME_BG_TTL_MS)
        .map((token) => Object.assign({token: token}, map[token]))
        .sort((a, b) => (b.updated || 0) - (a.updated || 0));
};

/**
 * A cheap content fingerprint of a file, so a resume only continues the *same*
 * file rather than any file that happens to share a name and byte length. It
 * hashes the first 64 KB (SHA-256 where the secure context provides SubtleCrypto)
 * and falls back to the last-modified time when it does not.
 *
 * @param {File} file The file to fingerprint.
 * @return {Promise} Resolves with a short opaque string.
 */
const fingerprintFile = async(file) => {
    const head = file.slice(0, Math.min(65536, file.size));
    if (window.crypto && window.crypto.subtle && window.isSecureContext) {
        try {
            const digest = await window.crypto.subtle.digest('SHA-256', await head.arrayBuffer());
            return 'sha256:' + Array.from(new Uint8Array(digest))
                .map((b) => b.toString(16).padStart(2, '0')).join('');
        } catch (e) {
            // Fall back to a coarser fingerprint below.
        }
    }
    return 'lm:' + (file.lastModified || 0) + ':' + file.size;
};

/**
 * POST one request to the endpoint. Resolves with the HTTP status and response
 * text; a network-level failure or an abort resolves with status 0 (treated as
 * transient by the retry path).
 *
 * The sensitive fields (a signed source URL) are sent in the request body, never
 * the query string, so they are not written to web-server/proxy access logs.
 *
 * @param {object} params Query-string parameters (action, id, ...); sesskey is added.
 * @param {Blob|string|null} body Request body, or null.
 * @param {string|null} contentType Content-Type for the body, or null for none.
 * @param {function|null} onprogress Optional callback given the bytes uploaded so far.
 * @param {object|null} controller Optional {cancelled, xhr} used to abort in-flight requests.
 * @return {Promise} Resolves with {status, text}.
 */
const postRequest = (params, body, contentType, onprogress, controller) => {
    return new Promise((resolve) => {
        if (controller && controller.cancelled) {
            resolve({status: 0, text: ''});
            return;
        }
        const query = Object.assign({sesskey: config.sesskey}, params);
        const qs = Object.keys(query).map((k) => encodeURIComponent(k) + '=' + encodeURIComponent(query[k])).join('&');
        const xhr = new XMLHttpRequest();
        xhr.open('post', config.wwwroot + ENDPOINT + '?' + qs);
        if (controller) {
            controller.xhr = xhr;
        }
        if (onprogress && xhr.upload) {
            xhr.upload.onprogress = (e) => onprogress(e.loaded);
        }
        xhr.onreadystatechange = () => {
            if (xhr.readyState === 4) {
                resolve({status: xhr.status, text: xhr.responseText});
            }
        };
        xhr.onerror = () => resolve({status: 0, text: ''});
        xhr.onabort = () => resolve({status: 0, text: ''});
        if (contentType) {
            xhr.setRequestHeader('Content-Type', contentType);
        }
        xhr.send(body);
    });
};

/**
 * Parse a JSON response, returning null when it cannot be parsed.
 *
 * @param {string} text The response text.
 * @return {object|null} The parsed object, or null.
 */
const parseJson = (text) => {
    try {
        return JSON.parse(text);
    } catch (e) {
        return null;
    }
};

/**
 * Resolve after the given number of milliseconds.
 *
 * @param {number} ms Milliseconds to wait.
 * @return {Promise} Resolves once the delay elapses.
 */
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Wait out a connectivity loss: resolve as soon as the browser reports it is back
 * online, the upload is cancelled, or a capped delay elapses (in case the 'online'
 * event was missed while the tab was suspended). Lets an outage pause an upload for
 * as long as it lasts rather than counting against its retry budget.
 *
 * @param {object} controller The {cancelled} abort controller.
 * @param {number} capMs The most it will wait before re-checking anyway.
 * @return {Promise} Resolves once back online, cancelled, or the cap elapses.
 */
const waitWhileOffline = (controller, capMs) => new Promise((resolve) => {
    if (controller && controller.cancelled) {
        resolve();
        return;
    }
    let settled = false;
    const finish = () => {
        if (settled) {
            return;
        }
        settled = true;
        if (typeof window !== 'undefined') {
            window.removeEventListener('online', finish);
        }
        resolve();
    };
    if (typeof window !== 'undefined') {
        window.addEventListener('online', finish);
    }
    setTimeout(finish, capMs);
});

/**
 * Pause before retrying a failed chunk. A connectivity loss — a status of 0 while
 * the browser reports itself offline (a sleeping laptop, dropped Wi-Fi) — is a pause,
 * not a countable failure: it waits for the connection to return without consuming
 * the retry budget, so an outage of any length resumes when the machine is awake and
 * online again. Any other transient failure backs off with the usual capped
 * exponential delay and is counted by the caller.
 *
 * @param {object} result The failed {status} response.
 * @param {number} attempt The attempt number, for the backoff curve.
 * @param {object} controller The {cancelled} abort controller.
 * @param {function|null} onWaiting Called with true while paused offline, false once it retries.
 * @return {Promise<boolean>} True when this was an offline pause (the caller must not count it).
 */
const backoffBeforeRetry = async(result, attempt, controller, onWaiting) => {
    const offline = result.status === 0 && typeof navigator !== 'undefined' && navigator.onLine === false;
    if (offline) {
        if (onWaiting) {
            onWaiting(true);
        }
        await waitWhileOffline(controller, BACKOFF_CAP_MS);
        if (onWaiting) {
            onWaiting(false);
        }
        return true;
    }
    await sleep(Math.min(BACKOFF_BASE_MS * Math.pow(2, attempt - 1), BACKOFF_CAP_MS));
    return false;
};

/**
 * Whether an HTTP status is a terminal client-side rejection. 408 and 429 are
 * transient and handled by the retry path; other 4xx responses are terminal.
 *
 * @param {number} status The HTTP status code.
 * @return {boolean} True if the upload should abort on this status.
 */
const isTerminal = (status) => status >= 400 && status < 500 && status !== 408 && status !== 429;

/**
 * Allocate a new upload token for the current context.
 *
 * @param {number} contextId The context id.
 * @param {object} controller The {cancelled, xhr} abort controller.
 * @return {Promise} Resolves with {id, maxbytes, chunksize}, or rejects with a message.
 */
const newToken = async(contextId, controller) => {
    const result = await postRequest({action: 'newtoken', contextid: contextId}, null, null, null, controller);
    const response = parseJson(result.text);
    if (result.status !== 200 || response === null || response.error !== undefined || !response.id) {
        throw new Error(response && response.error ? response.error : await getString('erroruploadfailed', 'repository_largefile'));
    }
    return response;
};

/**
 * Ask the server how many bytes of this upload it has stored, so a retry after a
 * lost response resumes from the true position.
 *
 * @param {string} token The upload token id.
 * @param {object} controller The {cancelled, xhr} abort controller.
 * @return {Promise} Resolves with {state, currentpos, length}, or null if unknown.
 */
const queryStatus = async(token, controller) => {
    const result = await postRequest({action: 'status', id: token}, null, null, null, controller);
    if (result.status !== 200) {
        return null;
    }
    const snap = parseJson(result.text);
    if (snap === null || snap.error !== undefined || snap.currentpos === undefined) {
        return null;
    }
    return snap;
};

/**
 * Upload one file chunk by chunk. A chunk is retried through transient network or
 * 5xx failures with exponential backoff, reconciling the resume position with the
 * server after each failure. A 4xx response or explicit server error is terminal.
 * The loop stops as soon as the controller is cancelled.
 *
 * @param {File} file The file to upload.
 * @param {string} token The upload token id.
 * @param {number} chunkSize The chunk size in bytes.
 * @param {function} onProgress Callback given (bytesConfirmed, total).
 * @param {object} controller The {cancelled, xhr} abort controller.
 * @param {number} resumeFrom Byte offset already stored server-side (for a resumed upload).
 * @param {function|null} onWaiting Called with true while paused offline, false once it resumes.
 * @return {Promise} Resolves true on success, false if cancelled, or rejects with a message.
 */
const uploadFileChunked = async(file, token, chunkSize, onProgress, controller, resumeFrom = 0, onWaiting = null) => {
    let confirmed = resumeFrom;
    let retries = 0;
    // A resumed upload already has its first chunk stored, so every remaining
    // chunk uses "proceed"; only a fresh upload (offset 0) sends "start".
    let started = resumeFrom > 0;
    onProgress(confirmed, file.size);
    while (confirmed < file.size) {
        if (controller.cancelled) {
            return false;
        }
        const start = confirmed;
        const end = Math.min(start + chunkSize, file.size);
        const params = start === 0
            ? {action: 'start', start: start, end: end, length: file.size, filename: file.name, id: token}
            : {action: 'proceed', start: start, end: end, id: token};
        const slice = file.slice(start, end);
        const result = await postRequest(params, slice, 'application/octet-stream',
            (loaded) => onProgress(start + loaded, file.size), controller);

        if (controller.cancelled) {
            return false;
        }
        if (result.status === 200) {
            const response = parseJson(result.text);
            if (response !== null && response.error !== undefined) {
                throw new Error(response.error);
            }
            if (response !== null) {
                confirmed = end;
                started = true;
                retries = 0;
                onProgress(confirmed, file.size);
                continue;
            }
        } else if (isTerminal(result.status)) {
            const key = result.status === 413 ? 'errorchunktoolarge' : 'erroruploadfailed';
            throw new Error(await getString(key, 'repository_largefile'));
        }

        // Transient failure. An offline period is a pause, not a countable failure —
        // it waits for the connection and does not consume the retry budget — so an
        // outage of any length (a sleeping laptop, dropped Wi-Fi) resumes when the
        // machine is awake and online again; a server-side transient error stays
        // bounded by MAX_RETRIES. Either way, reconcile with the server before retrying.
        const paused = await backoffBeforeRetry(result, retries + 1, controller, onWaiting);
        if (!paused) {
            retries++;
            if (retries > MAX_RETRIES) {
                throw new Error(await getString('erroruploadfailed', 'repository_largefile'));
            }
        }
        if (controller.cancelled) {
            return false;
        }
        if (started) {
            const snap = await queryStatus(token, controller);
            if (snap !== null && snap.length === file.size) {
                const advanced = snap.currentpos > confirmed;
                confirmed = (snap.state === STATE_COMPLETED || snap.currentpos >= file.size) ? file.size : snap.currentpos;
                if (advanced) {
                    retries = 0;
                }
                onProgress(confirmed, file.size);
            }
        }
    }
    return true;
};

/**
 * Finish a stalled Background Fetch upload from the foreground. The server is asked
 * which byte ranges are still missing, and only those are re-uploaded — out of
 * order, at their own offsets, through the same positional write the background
 * path uses — so the whole file is never re-sent. The upload completes on the
 * server once the last missing byte lands. A chunk retries transient failures with
 * the same backoff as a fresh upload; a 4xx or explicit error is terminal.
 *
 * @param {File} file The file being resumed (must be the same one).
 * @param {string} token The upload token id.
 * @param {number} chunkSize The chunk size in bytes.
 * @param {function} onProgress Callback given (bytesConfirmed, total).
 * @param {object} controller The {cancelled, xhr} abort controller.
 * @param {function|null} onWaiting Called with true while paused offline, false once it resumes.
 * @return {Promise} Resolves true on success, false if cancelled, or rejects with a message.
 */
const resumeBackgroundUpload = async(file, token, chunkSize, onProgress, controller, onWaiting = null) => {
    const statusResult = await postRequest({action: 'bgstatus', id: token}, null, null, null, controller);
    if (controller.cancelled) {
        return false;
    }
    const snap = parseJson(statusResult.text);
    if (statusResult.status !== 200 || snap === null || snap.error !== undefined || !Array.isArray(snap.missing)) {
        throw new Error(snap && snap.error ? snap.error : await getString('erroruploadfailed', 'repository_largefile'));
    }
    const missingBytes = snap.missing.reduce((sum, range) => sum + (range[1] - range[0]), 0);
    let confirmed = Math.max(0, file.size - missingBytes);
    onProgress(confirmed, file.size);
    for (let g = 0; g < snap.missing.length; g++) {
        const gapStart = snap.missing[g][0];
        const gapEnd = snap.missing[g][1];
        for (let start = gapStart; start < gapEnd; start += chunkSize) {
            const end = Math.min(start + chunkSize, gapEnd);
            const base = confirmed;
            const delivered = await uploadRangeChunk(file, token, start, end,
                (loaded) => onProgress(base + loaded, file.size), controller, onWaiting);
            if (!delivered) {
                return false;
            }
            confirmed += end - start;
            onProgress(confirmed, file.size);
        }
    }
    return true;
};

/**
 * Upload one byte range of a Background Fetch upload at its own offset, retrying
 * transient failures with the usual backoff. Only a well-formed success counts as
 * delivered: a 200 with an empty or unparseable body (a proxy page, a connection cut
 * after the headers) is treated as transient and retried, never counted — otherwise
 * the caller could finish while the server still lacks this chunk.
 *
 * @param {File} file The file being resumed.
 * @param {string} token The upload token id.
 * @param {number} start Offset the chunk begins at.
 * @param {number} end Offset the chunk ends at (exclusive).
 * @param {function} onLoaded Callback given the bytes of this chunk uploaded so far.
 * @param {object} controller The {cancelled, xhr} abort controller.
 * @param {function|null} onWaiting Called with true while paused offline, false once it resumes.
 * @return {Promise} Resolves true once delivered, false if cancelled; rejects on a terminal error.
 */
const uploadRangeChunk = async(file, token, start, end, onLoaded, controller, onWaiting = null) => {
    let retries = 0;
    for (;;) {
        if (controller.cancelled) {
            return false;
        }
        const result = await postRequest({action: 'bgchunk', id: token, start: start, end: end},
            file.slice(start, end), 'application/octet-stream', onLoaded, controller);
        if (controller.cancelled) {
            return false;
        }
        if (result.status === 200) {
            const response = parseJson(result.text);
            if (response !== null && response.error !== undefined) {
                throw new Error(response.error);
            }
            if (response !== null) {
                return true;
            }
        } else if (isTerminal(result.status)) {
            const key = result.status === 413 ? 'errorchunktoolarge' : 'erroruploadfailed';
            throw new Error(await getString(key, 'repository_largefile'));
        }
        // An offline period pauses without counting against the retry budget, so a
        // background-fetch resume also survives an outage of any length.
        const paused = await backoffBeforeRetry(result, retries + 1, controller, onWaiting);
        if (!paused) {
            retries++;
            if (retries > MAX_RETRIES) {
                throw new Error(await getString('erroruploadfailed', 'repository_largefile'));
            }
        }
    }
};

/**
 * Fetch a remote URL server-side into the token. The URL is sent in the POST body
 * so a signed link's credentials are not exposed in request logs.
 *
 * @param {string} url The URL to fetch.
 * @param {string} token The upload token id.
 * @param {object} controller The {cancelled, xhr} abort controller.
 * @return {Promise} Resolves true on success, false if cancelled, or rejects with a message.
 */
const fetchUrl = async(url, token, controller) => {
    const body = 'url=' + encodeURIComponent(url);
    const result = await postRequest({action: 'fetchurl', id: token}, body,
        'application/x-www-form-urlencoded', null, controller);
    if (controller.cancelled) {
        return false;
    }
    const response = parseJson(result.text);
    if (result.status !== 200 || response === null || response.error !== undefined) {
        throw new Error(response && response.error
            ? response.error : await getString('errordownloadfailed', 'repository_largefile'));
    }
    return true;
};

/**
 * Open the upload dialogue.
 *
 * @param {object} data The pubsub payload: {repoId, contextId, callback}.
 * @return {Promise} Resolves once the modal is created.
 */
const openUploadModal = async(data) => {
    const body = await Templates.render('repository_largefile/upload_dialogue', {});
    const modal = await SaveCancelModal.create({
        title: getString('pluginname', 'repository_largefile'),
        body: body,
        large: true,
        buttons: {save: getString('addfile', 'repository_largefile')},
    });

    const root = modal.getRoot();
    // Shared abort state: cancelling the modal flips `cancelled`, aborts any
    // in-flight request, and drops the server-side token so a closed dialogue
    // does not keep staging the file or fire the completion callback behind the
    // user's back.
    const controller = {cancelled: false, xhr: null, token: null};
    let selectedFile = null;
    let busy = false;
    // Unfinished uploads from a previous visit (same browser), offered for resume
    // once the user re-selects a matching file: the foreground slot for this context
    // plus any background uploads. resumeCandidates holds the validated set;
    // pendingResume is the one the re-selected file matched; resumeActive flips true
    // when a match is found.
    let resumeCandidates = [];
    let pendingResume = null;
    let resumeActive = false;
    // A previous foreground upload for this context whose partial the server no longer
    // has (expired or swept): remembered so re-selecting that same file explains the
    // fresh start ("your earlier upload expired") instead of silently resetting to 0.
    let expiredForeground = null;
    // Set once a file has been handed to Background Fetch: the browser now owns the
    // upload, so closing the dialogue must not delete its token.
    let backgroundHandedOff = false;

    const el = (selector) => root.find(selector).get(0);
    const setStatus = (text) => {
        const status = el('[data-region="status"]');
        if (status) {
            status.textContent = text;
        }
    };
    const showResume = (text) => {
        const region = el('[data-region="resume"]');
        if (region) {
            region.textContent = text;
            region.hidden = false;
        }
    };
    const hideResume = () => {
        const region = el('[data-region="resume"]');
        if (region) {
            region.hidden = true;
        }
    };
    const setProgress = (loaded, total) => {
        const pct = total > 0 ? Math.round(loaded * 100 / total) : 0;
        const bar = el('[data-region="progressbar"]');
        if (bar) {
            bar.style.width = pct + '%';
            bar.setAttribute('aria-valuenow', pct);
        }
        const label = el('[data-region="progresspct"]');
        if (label) {
            label.textContent = pct + '%';
        }
    };
    const abort = () => {
        // A background-fetch upload keeps running on its own; never tear it down.
        if (backgroundHandedOff) {
            return;
        }
        controller.cancelled = true;
        if (controller.xhr) {
            controller.xhr.abort();
        }
        // Drop the server-side token so a closed dialogue leaves no orphaned partial
        // file — whether the upload had started (controller.token) or only a *foreground*
        // resume was offered and then abandoned (pendingResume). A background upload is
        // never dropped here: its token belongs to an upload that may still be running
        // (or be recoverable), and it lives in the separate background store that this
        // dialogue does not own — so merely opening and closing the dialogue must not
        // delete it. Plain navigation does not call abort, so an upload left that way
        // stays resumable. Pass no controller so the cancelled flag does not short it.
        const droptoken = controller.token || (pendingResume && !pendingResume.background && pendingResume.token);
        if (droptoken) {
            postRequest({action: 'delete', id: droptoken}, null, null, null, null);
            controller.token = null;
            pendingResume = null;
        }
        writeResume(data.contextId, null);
    };

    /**
     * Validate one stored record against the server, returning it (with the server's
     * current offset) when it is still resumable, or null when it is gone/finished
     * (its stale record is then removed). A transient status failure returns null
     * *without* removing the record, so a later open can still offer it.
     *
     * @param {object} rec A resume record (foreground or background); has `background`.
     * @return {Promise} Resolves with the resumable record, or null.
     */
    const validateResume = async(rec) => {
        const result = await postRequest({action: 'status', id: rec.token}, null, null, null, controller);
        if (result.status !== 200) {
            return null;
        }
        const snap = parseJson(result.text);
        const drop = () => rec.background ? writeBgRecord(rec.token, null) : writeResume(data.contextId, null);
        if (snap === null || snap.error !== undefined || snap.currentpos === undefined) {
            // The server no longer has this token at all: re-selecting the same file
            // will start over, so remember a foreground one to explain that rather than
            // let the counter silently reset. Only a genuinely missing token counts as
            // expired — a completed or mismatched token below does not.
            if (!rec.background) {
                expiredForeground = {filename: rec.filename, size: rec.size};
            }
            drop();
            return null;
        }
        // Only trust the stored offset once the server has recorded a length that
        // matches this record's file; a not-yet-written token (length 0) resumes
        // from the start, and a non-zero length that differs is a different upload.
        if (snap.length && snap.length !== rec.size) {
            drop();
            return null;
        }
        const currentpos = snap.length === rec.size ? snap.currentpos : 0;
        if (snap.state === STATE_COMPLETED || currentpos >= rec.size) {
            // Already finished and staged on the server — nothing to resume, and not
            // expired, so clearing the stale record is enough (no "expired" message).
            drop();
            return null;
        }
        return Object.assign({}, rec, {currentpos: currentpos});
    };

    /**
     * Offer to resume an unfinished upload left from a previous visit. Gathers the
     * foreground slot for this context plus every background upload in it, validates
     * each against the server, and remembers those still resumable; the actual one
     * is chosen when the user re-selects the matching file. Records are only cleared
     * when the server *definitively* reports the token gone or finished.
     *
     * @return {Promise} Resolves once the banner is shown or dismissed.
     */
    const maybeOfferResume = async() => {
        pendingResume = null;
        resumeCandidates = [];
        const records = [];
        const fg = readResume(data.contextId);
        if (fg) {
            records.push(Object.assign({}, fg, {background: false}));
        }
        bgRecordsForContext(data.contextId).forEach((rec) => records.push(Object.assign({}, rec, {background: true})));
        if (!records.length) {
            hideResume();
            return;
        }
        for (let i = 0; i < records.length; i++) {
            const valid = await validateResume(records[i]);
            if (valid) {
                resumeCandidates.push(valid);
            }
        }
        if (!resumeCandidates.length) {
            hideResume();
            return;
        }
        // Name the newest candidate in the banner; the exact upload is matched to the
        // file the user re-selects (a context can hold more than one).
        const newest = resumeCandidates[0];
        const percent = newest.size > 0 ? Math.round((newest.currentpos || 0) * 100 / newest.size) : 0;
        showResume(await getString('resumeprompt', 'repository_largefile',
            {filename: newest.filename, percent: percent}));
    };

    // A file on the user's computer is read by this page, so leaving it pauses a
    // running chunked upload (the bytes stop flowing). Warn before navigating away
    // while one is in flight — but the progress is kept, so returning and picking
    // the same file resumes it. (For a truly unattended transfer, use a URL or the
    // server-side scheduled transfers on the Transfers page.)
    const beforeUnload = (e) => {
        if (busy) {
            e.preventDefault();
            e.returnValue = '';
            return '';
        }
        return undefined;
    };
    window.addEventListener('beforeunload', beforeUnload);

    root.on(ModalEvents.shown, async() => {
        selectedFile = null;
        resumeActive = false;
        busy = false;
        setProgress(0, 1);
        // Offer "keep uploading after I close this page" only where the browser can.
        if (BG_SUPPORTED) {
            const bgwrap = el('[data-region="bgwrap"]');
            if (bgwrap) {
                bgwrap.hidden = false;
            }
        }
        const input = el('[data-region="fileinput"]');
        if (input) {
            input.addEventListener('change', async() => {
                selectedFile = input.files.length ? input.files[0] : null;
                resumeActive = false;
                pendingResume = null;
                // Only continue a resume when the re-selected file is genuinely the
                // same one — same name, size and content fingerprint — so two
                // different files that share a name and length are never spliced.
                // With more than one candidate in this context, match the file to its
                // own record.
                const fingerprint = selectedFile ? await fingerprintFile(selectedFile) : null;
                const match = selectedFile ? resumeCandidates.find((c) => c.filename === selectedFile.name
                    && c.size === selectedFile.size && c.fingerprint === fingerprint) : null;
                if (match) {
                    pendingResume = match;
                    resumeActive = true;
                    setStatus(await getString('resumeready', 'repository_largefile', selectedFile.name));
                } else if (selectedFile && expiredForeground
                        && selectedFile.name === expiredForeground.filename
                        && selectedFile.size === expiredForeground.size) {
                    // The server no longer has this file's earlier partial, so the upload
                    // starts over — say so rather than silently resetting the counter to 0.
                    hideResume();
                    setStatus(await getString('uploadexpiredrestart', 'repository_largefile', selectedFile.name));
                } else {
                    hideResume();
                    setStatus(selectedFile ? selectedFile.name : '');
                }
            });
        }
        await maybeOfferResume();
    });

    // Cancelling or closing the dialogue aborts any in-flight transfer.
    root.on(ModalEvents.cancel, abort);
    root.on(ModalEvents.hidden, () => {
        window.removeEventListener('beforeunload', beforeUnload);
        abort();
        modal.destroy();
    });

    /**
     * Commit the URL tab: allocate a token and have the server fetch the URL into it.
     *
     * @return {Promise} Resolves true when staged, false when cancelled, or null when no URL was entered.
     */
    const importFromUrl = async() => {
        const urlInput = el('[data-region="urlinput"]');
        const url = urlInput ? urlInput.value.trim() : '';
        if (!url) {
            return null;
        }
        setStatus(await getString('uploading', 'repository_largefile'));
        const token = await newToken(data.contextId, controller);
        controller.token = token.id;
        return fetchUrl(url, token.id, controller);
    };

    /**
     * Hand the selected file to Background Fetch: it keeps running after the page
     * closes, so this dialogue's job is done once it is registered.
     *
     * @param {File} file The file to upload.
     * @return {Promise} Resolves once the handoff is complete and the dialogue closed.
     */
    const handOffToBackground = async(file) => {
        const bgtoken = await newToken(data.contextId, controller);
        if (bgtoken.maxbytes > 0 && file.size > bgtoken.maxbytes) {
            throw new Error(await getString('errordownloadtoobig', 'repository_largefile'));
        }
        // Track the token from now, so if service-worker registration or the fetch
        // handoff fails (or the user cancels during setup) the catch or abort deletes
        // its pre-sized file rather than orphaning it.
        controller.token = bgtoken.id;
        setStatus(await getString('bgstarting', 'repository_largefile'));
        await startBackgroundUpload(file, bgtoken);
        // Handoff succeeded: the browser owns the upload now. Refresh the picker when
        // it completes (a module-level listener, since this dialogue will be gone).
        // Key the callback by the Background Fetch registration id — the same id
        // the service worker attaches to its completion message — so this upload's
        // callback fires only when this upload finishes, not when any other
        // concurrent background upload from the same page does.
        ensureSwMessageListener();
        bgCompletionCallbacks.set('repository_largefile-' + bgtoken.id, data.callback);
        backgroundHandedOff = true;
        controller.token = null;
        // Remember it in the background store (keyed by token, not the per-context
        // foreground slot) so that, if it stalls — the browser fails the whole fetch
        // when any one chunk fails — the owner can re-select the same file and finish
        // the missing ranges rather than starting over. Kept out of the dialogue-owned
        // foreground slot so that opening and closing the dialogue never deletes a
        // running upload, and several background uploads can be in flight at once.
        // Cleared automatically once the server reports it complete.
        writeBgRecord(bgtoken.id, {
            contextId: data.contextId,
            filename: file.name,
            size: file.size,
            chunksize: bgtoken.chunksize,
            fingerprint: await fingerprintFile(file),
        });
        modal.hide();
        const notice = await Promise.all([
            getString('pluginname', 'repository_largefile'),
            getString('bgstarted', 'repository_largefile'),
            getString('ok', 'core'),
        ]);
        Notification.alert(notice[0], notice[1], notice[2]);
    };

    /**
     * Upload the selected file from this page: continue a matching unfinished upload
     * (a foreground one from its offset, a stalled background one by its missing
     * ranges) or start a fresh chunked upload.
     *
     * @param {File} file The file to upload.
     * @param {boolean} resuming Whether pendingResume matches this file and should be continued.
     * @param {object} run Shared run state; `backgroundResume` is set here before any bytes
     *        are sent so the caller's failure path can tell the two resume kinds apart.
     * @return {Promise} Resolves true when staged, false when cancelled; rejects on failure.
     */
    const uploadInForeground = async(file, resuming, run) => {
        let tokenId;
        let chunkSize;
        let resumeFrom = 0;
        // A stalled Background Fetch upload is finished by its missing ranges, not by a
        // sequential offset, so it takes a different resume path.
        run.backgroundResume = resuming && pendingResume.background === true;
        if (resuming) {
            // Carry on with the existing server-side token from where it stopped.
            tokenId = pendingResume.token;
            chunkSize = pendingResume.chunksize;
            resumeFrom = pendingResume.currentpos;
        } else {
            const token = await newToken(data.contextId, controller);
            if (token.maxbytes > 0 && file.size > token.maxbytes) {
                throw new Error(await getString('errordownloadtoobig', 'repository_largefile'));
            }
            tokenId = token.id;
            chunkSize = token.chunksize;
        }
        controller.token = tokenId;
        // Remember this upload so it can be resumed if the page is left before it
        // finishes (the server keeps the partial file and its position); the
        // fingerprint lets a resume confirm the re-selected file is the same one. A
        // background resume keeps its record in the background store (so a further
        // interruption still finishes by missing ranges); every other upload uses the
        // per-context foreground slot.
        const fingerprint = resuming ? pendingResume.fingerprint : await fingerprintFile(file);
        const record = {filename: file.name, size: file.size, chunksize: chunkSize, fingerprint: fingerprint};
        if (run.backgroundResume) {
            writeBgRecord(tokenId, Object.assign({contextId: data.contextId}, record));
        } else {
            writeResume(data.contextId, Object.assign({token: tokenId}, record));
        }
        hideResume();
        const uploadingText = await getString('uploading', 'repository_largefile');
        const waitingText = await getString('uploadwaiting', 'repository_largefile');
        setStatus(uploadingText);
        // While an offline period pauses the upload, show "waiting for the connection";
        // switch back to "uploading" as soon as it resumes.
        const onWaiting = (waiting) => setStatus(waiting ? waitingText : uploadingText);
        return run.backgroundResume
            ? resumeBackgroundUpload(file, tokenId, chunkSize, setProgress, controller, onWaiting)
            : uploadFileChunked(file, tokenId, chunkSize, setProgress, controller, resumeFrom, onWaiting);
    };

    root.on(ModalEvents.save, async(e) => {
        e.preventDefault();
        if (busy) {
            return;
        }
        // The active tab decides which source we commit.
        const urlTabActive = root.find('[data-region="tab-url"]').hasClass('active');
        // Whether this run is finishing a stalled Background Fetch upload: the success
        // and failure paths treat its recovery record and token differently (kept on
        // failure, not deleted). Set by uploadInForeground() before any bytes are sent.
        const run = {backgroundResume: false};
        try {
            busy = true;
            let staged;
            if (urlTabActive) {
                staged = await importFromUrl();
                if (staged === null) {
                    busy = false;
                    return;
                }
            } else {
                if (!selectedFile) {
                    busy = false;
                    return;
                }
                if (selectedFile.size === 0) {
                    // The chunk loop would send nothing for a zero-byte file and
                    // report a false success, so reject it up front.
                    throw new Error(await getString('erroremptyfile', 'repository_largefile'));
                }
                const resuming = resumeActive && pendingResume
                    && selectedFile.name === pendingResume.filename
                    && selectedFile.size === pendingResume.size;
                const bgCheck = el('[data-region="bgcheck"]');
                if (BG_SUPPORTED && bgCheck && bgCheck.checked && !resuming) {
                    await handOffToBackground(selectedFile);
                    return;
                }
                staged = await uploadInForeground(selectedFile, resuming, run);
            }
            // A cancelled transfer returns false: leave the picker untouched.
            if (controller.cancelled || staged === false) {
                return;
            }
            // The file is staged and about to be listed for selection, so clear the
            // token — otherwise closing the modal would delete it before the user
            // can pick it — and forget the (now completed) recovery record. Clearing
            // pendingResume too keeps the modal-hide abort() from deleting the file we
            // just finished.
            controller.token = null;
            if (run.backgroundResume) {
                writeBgRecord(pendingResume.token, null);
            } else {
                writeResume(data.contextId, null);
            }
            pendingResume = null;
            modal.hide();
            data.callback();
        } catch (error) {
            busy = false;
            setProgress(0, 1);
            // A failed background resume keeps its token, partial file and recovery
            // record, so the owner can try again and finish the still-missing ranges.
            // Every other failure drops a partially staged token so a retry does not
            // orphan it (a cancel has already deleted and cleared it via abort()) and
            // forgets the foreground record since that token is gone.
            if (!run.backgroundResume) {
                if (controller.token) {
                    postRequest({action: 'delete', id: controller.token}, null, null, null, null);
                    controller.token = null;
                }
                writeResume(data.contextId, null);
            }
            controller.token = null;
            if (controller.cancelled) {
                return;
            }
            const strings = await Promise.all([getString('error', 'core'), getString('ok', 'core')]);
            Notification.alert(strings[0], error.message, strings[1]);
        }
    });

    modal.show();
    return modal;
};

/**
 * Register the pubsub listener once.
 *
 * @return {void}
 */
const registerEventListeners = () => {
    if (!listenersRegistered) {
        subscribe('repository_largefile_upload', (data) => {
            openUploadModal(data);
        });
        listenersRegistered = true;
    }
};

/**
 * Initialise the upload module.
 *
 * @return {void}
 */
export const init = () => {
    registerEventListeners();
};

/**
 * Initialise the standalone Upload page (Transfers → Upload tab): bind the
 * given trigger button so clicking it opens the same dialogue the file picker
 * opens on its upload event. The completion callback surfaces a Moodle
 * notification pointing back at the Transfers page rather than closing the
 * page, so an admin can start another upload without navigating away.
 *
 * @param {object} data The bootstrap payload from the page:
 *        {contextId, transfersUrl, trigger}.
 * @return {void}
 */
export const initStandalone = (data) => {
    const trigger = document.querySelector(data.trigger);
    if (!trigger) {
        return;
    }
    trigger.addEventListener('click', () => {
        openUploadModal({
            repoId: 0,
            contextId: data.contextId,
            callback: async() => {
                const [ok, go] = await Promise.all([
                    getString('uploadtabsuccess', 'repository_largefile'),
                    getString('uploadtabgotransfers', 'repository_largefile'),
                ]);
                const link = document.createElement('a');
                link.href = data.transfersUrl;
                link.textContent = go;
                const span = document.createElement('span');
                span.textContent = ok + ' ';
                span.appendChild(link);
                Notification.addNotification({
                    type: 'success',
                    message: span.outerHTML,
                });
            },
        });
    });
};
